    "warehouse_worker",
    "factory_work_assembly",
  ];
  if (boostedJobs.includes(job.id)) {
    const newbieBonus = job.id === "waste_recycling" ? 2 : 2;
    pay += newbieBonus;
  }
}
state.employment.completedShifts[job.id] =
