}
// 已获称号加成持续生效
var titleBonus = state.flags._jobTitles[job.id] || 0;
if (titleBonus === 2) pay = Math.floor(pay * 1.08);
else if (titleBonus === 3) pay = Math.floor(pay * 1.15);

