function renderActionsTab(state, parent) {
  const actions = getAvailableActions(state);

  // === 地点氛围描写（每日轮换，让城市有生命感）===
  if (typeof getLocationFlavor === "function") {
    var locId = state.trade && state.trade.currentLocation;
    var flavorText = getLocationFlavor(locId, state.player.day);
    if (flavorText) {
      var flavorBox = document.createElement("div");
      flavorBox.style.cssText =
        "margin-bottom:12px;padding:9px 12px;background:rgba(255,255,255,0.03);border-left:3px solid var(--border);border-radius:0 6px 6px 0;color:var(--text-muted);font-size:12px;font-style:italic;line-height:1.5;";
      flavorBox.textContent = flavorText;
      parent.appendChild(flavorBox);
    }
  }

  // === 今日智能建议（心智驱动，不限数量，滚动展示）===
  {
    var tips = getDailyActionTips(state);
    if (tips.length > 0) {
      var tipBox = document.createElement("div");
      tipBox.style.cssText =
        "margin-bottom:14px;padding:10px 12px;background:rgba(74,158,92,0.06);border:1px solid rgba(74,158,92,0.25);border-radius:8px;";
      var mental = (state.player && state.player.mental) || 0;
      var mentalTag =
        mental >= 80
          ? "🧠 专家洞察"
          : mental >= 60
            ? "💡 进阶建议"
            : "💡 今日建议";
      // 标题行（静态文字，safe to innerHTML）
      var titleDiv = document.createElement("div");
      titleDiv.style.cssText =
        "font-size:10px;color:var(--accent);font-weight:700;margin-bottom:6px;letter-spacing:0.5px;";
      titleDiv.innerHTML =
        mentalTag +
        ' <span style="font-size:9px;color:var(--text-muted);font-weight:400;">（心智' +
        mental +
        "）</span>";
      tipBox.appendChild(titleDiv);
      // 建议列表（用 textContent 避免 XSS）
      var listDiv = document.createElement("div");
      listDiv.style.cssText =
        "max-height:110px;overflow-y:auto;padding-right:2px;";
      tips.forEach(function (t) {
        var item = document.createElement("div");
        item.style.cssText =
          "font-size:12px;color:var(--text-secondary);padding:2px 0;border-bottom:1px solid rgba(255,255,255,0.04);";
        item.textContent = t;
        listDiv.appendChild(item);
      });
      tipBox.appendChild(listDiv);
      parent.appendChild(tipBox);
    }
  }

  // 分离出行和其他行动
  const travelActions = actions.filter((a) => a.id.startsWith("travel_"));
  const housingActions = actions.filter(
    (a) => a.id.startsWith("housing_") || a.id.startsWith("storage_"),
  );
  const otherActions = actions.filter(
    (a) =>
      !a.id.startsWith("travel_") &&
      !a.id.startsWith("housing_") &&
      !a.id.startsWith("storage_"),
  );

  // === 🌍 出行区域（置顶，醒目） ===
  if (travelActions.length > 0) {
    const travelSection = document.createElement("div");
    travelSection.style.cssText = "margin-bottom:16px;";
    travelSection.innerHTML =
      '<h3 style="color:var(--accent);margin-bottom:8px;font-size:14px;">🌍 出行 — 点击前往其他地点</h3>';

    const travelGrid = document.createElement("div");
    travelGrid.className = "action-cards";
    travelGrid.style.gridTemplateColumns =
      "repeat(auto-fill, minmax(180px, 1fr))";

    for (const action of travelActions) {
      const destKey = action.id.replace("travel_", "");
      const dest =
        typeof getLocation === "function" ? getLocation(destKey) : null;
      const jobCount = dest ? (dest.jobs || []).length : 0;

      // 服务标签
      const badges =
        typeof getLocationServiceBadges === "function"
          ? getLocationServiceBadges(destKey)
          : [];
      const badgeStr =
        badges.length > 0
          ? badges
              .map(
                (b) =>
                  `<span style="font-size:9px;padding:2px 5px;border-radius:3px;background:${b.bg};color:${b.color};border:1px solid ${b.color};">${b.icon} ${b.label}</span>`,
              )
              .join(" ")
          : "";

      // 检查该地点的最佳买卖机会
      let tradeHint = "";
      if (typeof GOODS !== "undefined" && state.trade.goodsPrices[destKey]) {
        const opportunities = [];
        for (const good of GOODS) {
          const destPrice = state.trade.goodsPrices[destKey]?.[good.id];
          const curPrice =
            state.trade.goodsPrices[state.trade.currentLocation]?.[good.id];
          if (destPrice && curPrice && destPrice > curPrice * 1.3) {
            opportunities.push(`${good.name}📈`);
          }
        }
        if (opportunities.length > 0)
          tradeHint = `<br>🤑 可卖: ${opportunities.slice(0, 2).join(" ")}`;
      }

      const card = document.createElement("div");
      card.className = "action-card";
      card.style.borderColor = "var(--accent)";
      card.style.background =
        "linear-gradient(135deg, var(--bg-card), rgba(0,180,216,0.05))";
      card.innerHTML = `
        <div style="display:flex;justify-content:space-between;align-items:center;">
          <div class="card-title" style="font-size:15px;color:var(--accent);">${dest ? dest.name : destKey}</div>
          <span style="font-size:10px;color:var(--text-muted);">🚶 前往</span>
        </div>
        <div class="card-desc" style="font-size:11px;margin:4px 0;">
          ${dest ? dest.desc : ""}
          ${jobCount > 0 ? `<br>💼 ${jobCount}种工作机会` : ""}
          ${tradeHint}
        </div>
        ${badgeStr ? `<div style="margin-top:6px;display:flex;flex-wrap:wrap;gap:3px;">${badgeStr}</div>` : ""}
      `;
      card.addEventListener("click", () => {
        action.handler();
        renderAll();
      });
      travelGrid.appendChild(card);
    }
    travelSection.appendChild(travelGrid);
    parent.appendChild(travelSection);
  }

  // === 🏠 住所/仓储区域（醒目） ===
  if (housingActions.length > 0) {
    const houseSection = document.createElement("div");
    houseSection.style.cssText =
      "margin-bottom:16px;padding:12px;background:rgba(243,156,18,0.05);border:1px solid rgba(243,156,18,0.2);border-radius:var(--radius-md);";
    houseSection.innerHTML =
      '<h3 style="color:var(--warning);margin-bottom:8px;font-size:14px;">🏠 住所 & 仓储 — 提升生活质量</h3>';
    const houseGrid = document.createElement("div");
    houseGrid.className = "action-cards";
    houseGrid.style.gridTemplateColumns =
      "repeat(auto-fill, minmax(200px, 1fr))";
    for (const action of housingActions) {
      houseGrid.appendChild(createActionCard(action, state));
    }
    houseSection.appendChild(houseGrid);
    parent.appendChild(houseSection);
  }

  // === 其他行动 ===
  if (otherActions.length > 0) {
    const otherLabel = document.createElement("h3");
    otherLabel.style.cssText =
      "color:var(--text-muted);margin-bottom:6px;font-size:13px;";
    otherLabel.textContent = "⚡ 行动";
    parent.appendChild(otherLabel);

    const cards = document.createElement("div");
    cards.className = "action-cards";
    for (const action of otherActions) {
      cards.appendChild(createActionCard(action, state));
    }
    parent.appendChild(cards);
  }

  // === Phase 2 深度交互入口 ===
  {
    const phase2Box = document.createElement("div");
    phase2Box.style.cssText =
      "margin-top:20px;padding:16px;background:linear-gradient(135deg, rgba(142,119,217,0.08), rgba(255,255,255,0.02));border:1px solid rgba(142,119,217,0.2);border-radius:var(--radius-md);";
    phase2Box.innerHTML = `
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:12px;">
        <h4 style="color:var(--accent);margin:0;font-size:14px;">🌟 Phase 2 深度交互</h4>
        <span style="font-size:9px;color:var(--text-muted);">点击打开新系统</span>
      </div>
      <div style="display:grid;grid-template-columns:repeat(3, 1fr);gap:8px;">
        <button onclick="switchTab('workplace_social')" class="btn btn-sm" style="padding:8px 12px;">👥 职场社交</button>
        <button onclick="switchTab('family')" class="btn btn-sm" style="padding:8px 12px;">👨‍👩‍👧 家庭</button>
        <button onclick="switchTab('personal_growth')" class="btn btn-sm" style="padding:8px 12px;">🌱 个人成长</button>
      </div>
    `;
    parent.appendChild(phase2Box);
  }
}

function createActionCard(action, state) {
  const card = document.createElement("div");
  card.className = "action-card";
  if (action.disabled) {
    card.classList.add("disabled");
  }

  card.innerHTML = `
    <div class="card-icon">${action.icon}</div>
    <div class="card-title">${action.name}</div>
    <div class="card-desc">${action.desc}</div>
    <div class="card-meta">
      ${action.apCost ? `<span class="ap-cost">⚡${action.apCost}</span>` : ""}
      ${action.payEstimate ? `<span class="pay-estimate">💰 ¥${action.payEstimate}</span>` : ""}
      ${action.costEstimate ? `<span class="cost-estimate">💸 ¥${action.costEstimate}</span>` : ""}
      ${action.reqFail ? `<span class="req-fail">⚠ ${action.reqFail}</span>` : ""}
    </div>
    ${action.payTags && action.payTags.length > 0 ? `<div style="font-size:9px;color:var(--accent);margin-top:2px;letter-spacing:0.5px;">${action.payTags.join(" ")}</div>` : ""}
  `;

  if (!action.disabled) {
    card.addEventListener("click", () => {
      if (action.handler) {
        action.handler();
        renderAll();
      }
    });
  }

  return card;
}

// ====== Map Tab =====
function renderMapTab(state, parent) {
  const locKey = state.trade.currentLocation;
  const loc = getLocation(locKey);
  const reachable = new Set(getReachableLocations(locKey));
  reachable.add(locKey);

  const container = document.createElement("div");
  container.style.cssText = "display:flex;flex-direction:column;gap:16px;";

  // 标题
  const title = document.createElement("div");
  title.innerHTML = `
    <h3 style="color:var(--text-muted);margin-bottom:4px;">🗺️ 城市地图</h3>
    <p style="font-size:12px;color:var(--text-secondary);">
      当前在 <strong style="color:var(--accent);">${loc ? loc.name : "未知"}</strong> — 点击地点直接前往（仅显示已探索的相邻地点可到达的）
    </p>
  `;
  container.appendChild(title);

  // === ⭐ 快速出行置顶区（解决"地图没了"问题） ===
  const reachableList = Array.from(reachable).filter((k) => k !== locKey);
  if (reachableList.length > 0) {
    const quick = document.createElement("div");
    quick.style.cssText =
      "padding:14px;background:linear-gradient(135deg, var(--bg-card), rgba(0,180,216,0.08));border:1px solid var(--accent);border-radius:var(--radius-md);";
    quick.innerHTML = `
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:10px;">
        <h4 style="color:var(--accent);margin:0;font-size:14px;">🚶 快速出行</h4>
        <span style="font-size:10px;color:var(--text-muted);">从 ${loc ? loc.name : "当前位置"} 出发</span>
      </div>
      <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(140px,1fr));gap:8px;">
    `;
    for (const destKey of reachableList) {
      const dest = getLocation(destKey);
      if (!dest) continue;
      const destType =
        dest.type === "commercial"
          ? "🛒商业"
          : dest.type === "industrial"
            ? "🏭工业"
            : dest.type === "residential"
              ? "🏘️居住"
              : dest.type === "service"
                ? "🏥服务"
                : dest.type === "education"
                  ? "📚教育"
                  : dest.type === "corporate"
                    ? "🏢职场"
                    : dest.type === "recreation"
                      ? "🌳休闲"
                      : dest.type === "institutional"
                        ? "🏫机构"
                        : "📍其他";
      quick.innerHTML += `
        <button class="quick-travel-btn" data-dest="${destKey}" style="
          padding:10px 12px;
          background:var(--bg-secondary);
          border:1px solid var(--border);
          border-radius:6px;
          cursor:pointer;
          text-align:left;
          color:var(--text-primary);
          font-size:12px;
          transition:all 0.15s;
        " onmouseover="this.style.borderColor='var(--accent)';this.style.background='rgba(0,180,216,0.06)';"
           onmouseout="this.style.borderColor='var(--border)';this.style.background='var(--bg-secondary)';">
          <div style="font-weight:600;color:var(--accent);">📍 ${dest.name}</div>
          <div style="font-size:10px;color:var(--text-muted);margin-top:2px;">${destType}</div>

content.content:
1	/**
2	 * 存档系统 — localStorage 多槽位持久化
3	 *
4	 * 5个手动存档槽 + 1个自动存档
5	 * 索引键: 'city_life_story_index' — 存储各槽位元信息
6	 * 存档键: 'city_life_story_slot_N' (N=1..5) + 'city_life_story_autosave'
7	 */
8	
9	const NUM_SLOTS = 5;
10	const SLOT_PREFIX = "city_life_story_slot_";
11	const AUTO_SAVE_KEY = "city_life_story_autosave";
12	const INDEX_KEY = "city_life_story_index";
13	
14	/** 获取槽位键 */
15	function slotKey(n) {
16	  return SLOT_PREFIX + n;
17	}
18	
19	/** 读取存档索引 */
20	function getSaveIndex() {
21	  try {
22	    const raw = localStorage.getItem(INDEX_KEY);
23	    return raw ? JSON.parse(raw) : {};
24	  } catch (e) {
25	    return {};
26	  }
27	}
28	
29	/** 写入存档索引 */
30	function setSaveIndex(index) {
31	  localStorage.setItem(INDEX_KEY, JSON.stringify(index));
32	}
33	
34	/** 生成"那时候你..."回忆文案（存储于索引，读档时展示） */
35	function generateSaveNarrative(state) {
36	  var p = state.player;
37	  var r = state.resources;
38	  var day = p.day;
39	  var cash = (r.cash || 0) + (r.bankBalance || 0);
40	  var debt = (r.villageDebt || 0) + (r.bankDebt || 0);
41	
42	  var locNames = {
43	    slum: "城中村",
44	    wholesaleMarket: "批发市场",
45	    construction: "建筑工地",
46	    factoryZone: "工厂区",
47	    school: "大学城",
48	    commercialDist: "商业区",
49	    techPark: "科技园",
50	    hospital: "医院",
51	    bank: "银行",
52	    park: "公园",
53	    trainingCenter: "培训中心",
54	  };
55	  var loc = locNames[state.trade && state.trade.currentLocation] || "城市某处";
56	
57	  if (p.phase === "corporate") {
58	    var rank = (state.corporate && state.corporate.rank) || "P5";
59	    var company = (state.corporate && state.corporate.company) || "科技公司";
60	    return (
61	      "那时候你已经是" +
62	      company +
63	      "的" +
64	      rank +
65	      "，在职场打拼了" +
66	      day +
67	      "天，存款" +
68	      (cash >= 1000 ? (cash / 1000).toFixed(1) + "万" : "¥" + cash) +
69	      "元。"
70	    );
71	  }
72	
73	  var tail = "";
74	  var dreamId = state.flags && state.flags._dreamId;
75	  if (dreamId) {
76	    var dreamNames = {
77	      restaurant: "开餐馆",
78	      apartment: "买房",
79	      abroad: "出国",
80	      investor: "投资大亨",
81	      celebrity: "城市名人",
82	    };
83	    tail = "，梦想着" + (dreamNames[dreamId] || dreamId);
84	  }
85	
86	  if (day <= 15) {
87	    return (
88	      "那时候你刚来这座城市第" +
89	      day +
90	      "天，在" +
91	      loc +
92	      "落脚，兜里" +
93	      (debt > 0
94	        ? "还欠着¥" + debt.toLocaleString() + "的债"
95	        : "有¥" + cash.toLocaleString()) +
96	      tail +
97	      "。"
98	    );
99	  } else if (cash < 500) {
100	    return (
101	      "那时候你在城里漂了" +
102	      day +
103	      "天，手里只剩¥" +
104	      cash.toLocaleString() +
105	      "，日子过得很紧巴" +
106	      tail +
107	      "。"
108	    );
109	  } else if (cash >= 50000) {
110	    return (
111	      "那时候你在" +
112	      loc +
113	      "打拼了" +
114	      day +
115	      "天，已经攒下" +
116	      Math.round(cash / 1000) +
117	      "千元，离梦想越来越近" +
118	      tail +
119	      "。"
120	    );
121	  } else {
122	    return (
123	      "那时候你在城里走过了" +
124	      day +
125	      "天，在" +
126	      loc +
127	      "一步一步往前走，手里有¥" +
128	      cash.toLocaleString() +
129	      tail +
130	      "。"
131	    );
132	  }
133	}
134	
135	/**
136	 * 生成读档时的回忆文案（P1 - 存档快照）
137	 *
138	 * 基于存档快照生成"那时候你..."的叙事文案
139	 */
140	
141	/** 保存游戏到指定槽位（1-5） */
142	function saveGame(slot) {
143	  if (slot < 1 || slot > NUM_SLOTS) {
144	    StateManager.addMessage("⚠️ 无效的存档槽位。", "danger");
145	    return false;
146	  }
147	
148	  try {
149	    const state = StateManager.getState();
150	    state.lastPlayedAt = Date.now();
151	
152	    const saveData = JSON.parse(JSON.stringify(state));
153	    // 附加存档快照（用于读档回忆文案）
154	    if (typeof createSnapshot === "function") {
155	      saveData._snapshot = createSnapshot(state);
156	    }
157	    // 精简消息日志
158	    if (saveData.messageLog && saveData.messageLog.length > 200) {
159	      saveData.messageLog = saveData.messageLog.slice(-200);
160	    }
161	
162	    localStorage.setItem(slotKey(slot), JSON.stringify(saveData));
163	
164	    // 更新索引
165	    const index = getSaveIndex();
166	    index[slot] = {
167	      day: state.player.day,
168	      phase: state.player.phase,
169	      cash: state.resources.cash,
170	      age: state.player.age,
171	      debt: state.resources.debt,
172	      totalEarned: state.resources.totalEarned,
173	      location: state.trade.currentLocation,
174	      rank: state.player.phase === "corporate" ? state.corporate.rank : null,
175	      savedAt: Date.now(),
176	      narrative: generateSaveNarrative(state),
177	      mode: state.flags._isScenarioMode
178	        ? "📜" + (state.flags._scenarioName || "剧本")
179	        : state.flags._isSandboxMode
180	          ? "⚙️沙盒"
181	          : "🎯经典",
182	    };
183	    setSaveIndex(index);
184	
185	    StateManager.addMessage(
186	      `💾 已保存到槽位 ${slot}（第${state.player.day}天，¥${state.resources.cash.toLocaleString()}）`,
187	      "success",
188	    );
189	    return true;
190	  } catch (e) {
191	    console.error("存档失败:", e);
192	    StateManager.addMessage("⚠️ 存档失败: " + e.message, "danger");
193	    return false;
194	  }
195	}
196	
197	/** 自动存档 */
198	function autoSave() {
199	  try {
200	    const state = StateManager.getState();
201	    const saveData = JSON.parse(JSON.stringify(state));
202	    saveData.lastPlayedAt = Date.now();
203	    // 附加存档快照（用于读档回忆文案）
204	    if (typeof createSnapshot === "function") {
205	      saveData._snapshot = createSnapshot(state);
206	    }
207	    if (saveData.messageLog && saveData.messageLog.length > 200) {
208	      saveData.messageLog = saveData.messageLog.slice(-200);
209	    }
210	    localStorage.setItem(AUTO_SAVE_KEY, JSON.stringify(saveData));
211	
212	    // 更新索引中的自动存档信息
213	    const index = getSaveIndex();
214	    index._auto = {
215	      day: state.player.day,
216	      phase: state.player.phase,
217	      cash: state.resources.cash,
218	      age: state.player.age,
219	      debt: state.resources.debt,
220	      totalEarned: state.resources.totalEarned,
221	      location: state.trade.currentLocation,
222	      rank: state.player.phase === "corporate" ? state.corporate.rank : null,
223	      savedAt: Date.now(),
224	      narrative: generateSaveNarrative(state),
225	    };
226	    setSaveIndex(index);
227	  } catch (e) {
228	    /* 静默 */
229	  }
230	}
231	
232	/** 从指定槽位加载存档 */
233	function loadGame(slot) {
234	  try {
235	    let key;
236	    if (slot === "_auto") {
237	      key = AUTO_SAVE_KEY;
238	    } else if (typeof slot === "number" && slot >= 1 && slot <= NUM_SLOTS) {
239	      key = slotKey(slot);
240	    } else {
241	      // 兼容旧版：尝试直接以 slot 为键
242	      key = slot;
243	    }
244	
245	    const json = localStorage.getItem(key);
246	    if (!json) return null;
247	    return JSON.parse(json);
248	  } catch (e) {
249	    console.error("读档失败:", e);
250	    return null;
251	  }
252	}
253	
254	/** 删除指定槽位的存档 */
255	function deleteSave(slot) {
256	  if (slot === "_auto") {
257	    localStorage.removeItem(AUTO_SAVE_KEY);
258	    const index = getSaveIndex();
259	    delete index._auto;
260	    setSaveIndex(index);
261	    return;
262	  }
263	  if (slot < 1 || slot > NUM_SLOTS) return;
264	  localStorage.removeItem(slotKey(slot));
265	  const index = getSaveIndex();
266	  delete index[slot];
267	  setSaveIndex(index);
268	}
269	
270	/** 检查指定槽位是否有存档 */
271	function hasSave(slot) {
272	  if (slot === "_auto") return localStorage.getItem(AUTO_SAVE_KEY) !== null;
273	  if (typeof slot === "number")
274	    return localStorage.getItem(slotKey(slot)) !== null;
275	  // 兼容检查任意存档
276	  const index = getSaveIndex();
277	  return Object.keys(index).length > 0;
278	}
279	
280	/** 获取存档槽位的显示信息 */
281	function getSlotInfo(slot) {
282	  if (slot === "_auto") {
283	    const index = getSaveIndex();
284	    const meta = index._auto;
285	    if (!meta) {
286	      const raw = localStorage.getItem(AUTO_SAVE_KEY);
287	      if (!raw) return null;
288	      try {
289	        const data = JSON.parse(raw);
290	        var autoMode = "";
291	        if (data.flags && data.flags._isScenarioMode) {
292	          autoMode = "📜" + (data.flags._scenarioName || "剧本");
293	        } else if (data.flags && data.flags._isSandboxMode) {
294	          autoMode = "⚙️沙盒";
295	        }
296	        return {
297	          day: data.player?.day || 1,
298	          phase: data.player?.phase || "street",
299	          cash: data.resources?.cash || 0,
300	          age: data.player?.age || 20,
301	          debt: data.resources?.debt || 0,
302	          totalEarned: data.resources?.totalEarned || 0,
303	          location: data.trade?.currentLocation || "slum",
304	          rank:
305	            data.player?.phase === "corporate" ? data.corporate?.rank : null,
306	          savedAt: data.lastPlayedAt || data.createdAt,
307	          mode: autoMode,
308	        };
309	      } catch (e) {
310	        return null;
311	      }
312	    }
313	    return { ...meta, slot: "_auto", label: "🤖 自动存档" };
314	  }
315	
316	  const index = getSaveIndex();
317	  const meta = index[slot];
318	  if (!meta) return null;
319	
320	  const date = new Date(meta.savedAt);
321	  const loc =
322	    typeof LOCATIONS !== "undefined" && LOCATIONS[meta.location]
323	      ? LOCATIONS[meta.location].name
324	      : meta.location;
325	
326	  return {
327	    slot,
328	    label: `存档槽位 ${slot}`,
329	    day: meta.day,
330	    phase: meta.phase,
331	    cash: meta.cash,
332	    age: meta.age,
333	    debt: meta.debt,
334	    totalEarned: meta.totalEarned,
335	    location: loc,
336	    rank: meta.rank,
337	    date: date.toLocaleString("zh-CN"),
338	    savedAt: meta.savedAt,
339	    mode: meta.mode,
340	  };
341	}
342	
343	/** 获取所有存档槽位信息 */
344	function getAllSlots() {
345	  const slots = [];
346	  // 自动存档
347	  const auto = getSlotInfo("_auto");
348	  if (auto) slots.push(auto);
349	  // 手动存档 1-5
350	  for (let i = 1; i <= NUM_SLOTS; i++) {
351	    const info = getSlotInfo(i);
352	    if (info) slots.push(info);
353	  }
354	  return slots;
355	}
356	
357	/** 获取所有槽位（含空槽位） */
358	function getAllSlotsWithEmpty() {
359	  const slots = [];
360	  // 自动存档
361	  const auto = getSlotInfo("_auto");
362	  slots.push(auto || { slot: "_auto", label: "🤖 自动存档", empty: true });
363	  // 手动存档
364	  for (let i = 1; i <= NUM_SLOTS; i++) {
365	    const info = getSlotInfo(i);
366	    slots.push(info || { slot: i, label: `存档槽位 ${i}`, empty: true });
367	  }
368	  return slots;
369	}
