371	function createSnapshot(state) {
372	  var snapshot = {
373	    // 基础信息
374	    day: state.player.day,
375	    age: state.player.age,
376	    phase: state.player.phase,
377	    rank: state.player.phase === "corporate" ? state.corporate.rank : null,
378	    cash: state.resources.cash,
379	    bankBalance: state.resources.bankBalance,
380	    debt: state.resources.debt,
381	    totalEarned: state.resources.totalEarned,
382	
383	    // 需求状态
384	    hunger: state.needs?.hunger || 0,
385	    fatigue: state.needs?.fatigue || 0,
386	    hygiene: state.needs?.hygiene || 0,
387	    happiness: state.needs?.happiness || 0,
388	    health: state.status?.health || 100,
389	
390	    // 属性
391	    physique: state.player.physique || 0,
392	    intelligence: state.player.intelligence || 0,
393	    agility: state.player.agility || 0,
394	    mental: state.player.mental || 0,
395	
396	    // 疾病状态
397	    illnesses: (function () {
398	      var ills = [];
399	      if (state.status?.illnesses && state.status.illnesses.length > 0) {
400	        for (var i = 0; i < state.status.illnesses.length; i++) {
401	          var ill = state.status.illnesses[i];
402	          var illData =
403	            typeof getIllnessData === "function" ? getIllnessData(ill) : null;
404	          ills.push({
405	            id: ill.id,
406	            name: illData?.name || ill.name || "未知疾病",
407	            severity: illData?.severity || 1,
408	            stage: ill.stage || 1,
409	            health: ill.health || 0,
410	          });
411	        }
412	      }
413	      return ills;
414	    })(),
415	
416	    // 食材库存
417	    ingredients: (function () {
418	      var ings = [];
419	      if (state.inventory?.items && state.inventory.items.length > 0) {
420	        var ingredientItems = state.inventory.items.filter(function (item) {
421	          return item.isIngredient || item.ingredientType;
422	        });
423	        for (var j = 0; j < ingredientItems.length; j++) {
424	          var ing = ingredientItems[j];
425	          ings.push({
426	            itemId: ing.itemId || ing.id,
427	            quantity: ing.quantity || ing.qty || 0,
428	            expiredAt: ing.expiredAt,
429	          });
430	        }
431	      }
432	      return ings;
433	    })(),
434	
435	    // 烹饪技能
436	    cookingLevel: (function () {
437	      if (typeof getCookingLevel === "function") {
438	        return getCookingLevel(state);
439	      }
440	      return 0;
441	    })(),
442	
443	    // 当前地点
444	    location: state.trade?.currentLocation || "slum",
445	
446	    // 梦想
447	    dreamId: state.flags?._dreamId || null,
448	    dreamMilestone: state.flags?._dreamMilestone || 0,
449	
450	    // 技能树
451	    skillBranches: state.skillBranches || {},
452	    talentNodes: state.talentNodes || {},
453	
454	    // 关系
455	    relationshipCount: Object.keys(state.relationships || {}).filter(
456	      function (npcId) {
457	        var r = state.relationships[npcId];
458	        return r && r.met && (r.affinity || 0) >= 30;
459	      },
460	    ).length,
461	
462	    // 公司历史（职场阶段）
463	    corpHistory: (function () {
464	      if (state.player.phase === "corporate" && state.corporate) {
465	        return {
466	          company: state.corporate.company?.name || null,
467	          rank: state.corporate.rank,
468	          teamSize: state.corporate.team?.length || 0,
469	          perfHistory: state.corporate.perfHistory || [],
470	          completedProjects: state.corporate.completedProjects || [],
471	          consecutiveC: state.corporate.consecutiveC || 0,
472	        };
473	      }
474	      return null;
475	    })(),
476	
477	    // 企业命运（如果有）
478	    enterpriseFate: (function () {
479	      if (state.enterpriseFate?.companies) {
480	        var companies = [];
481	        for (var cid in state.enterpriseFate.companies) {
482	          var co = state.enterpriseFate.companies[cid];
483	          companies.push({
484	            id: cid,
485	            name: co.name,
486	            phase: co.phase,
487	            health: co.health,
488	            ipoed: co.ipoed,
489	            ceasedExistence: co.ceasedExistence,
490	          });
491	        }
492	        return { companies: companies };
493	      }
494	      return null;
495	    })(),
496	  };
497	
498	  return snapshot;
499	}
