501	/**
502	 * 生成读档时的回忆文案（P1 - 存档快照）
503	 *
504	 * 基于存档快照生成"那时候你..."的叙事文案
505	 */
506	function getLoadMemoryText(snapshot) {
507	  if (!snapshot) return "";
508	
509	  var day = snapshot.day;
510	  var cash = (snapshot.cash || 0) + (snapshot.bankBalance || 0);
511	  var debt = snapshot.debt || 0;
512	  var phase = snapshot.phase || "street";
513	
514	  // 职场阶段
515	  if (phase === "corporate") {
516	    var rank = snapshot.rank || "P5";
517	    var company = snapshot.corpHistory?.company || "科技公司";
518	    var teamSize = snapshot.corpHistory?.teamSize || 0;
519	    var perfCount = snapshot.corpHistory?.perfHistory?.length || 0;
520	
521	    return (
522	      "那时候你已经是" +
523	      company +
524	      "的" +
525	      rank +
526	      "，在职场打拼了" +
527	      day +
528	      "天，带领" +
529	      teamSize +
530	      "人团队，完成了" +
531	      perfCount +
532	      "次绩效评审，存款" +
533	      (cash >= 1000
534	        ? Math.round(cash / 1000) + "千元"
535	        : "¥" + Math.round(cash)) +
536	      "元。"
537	    );
538	  }
