1468	  html += '<p style="margin:0 0 12px;color:var(--text-muted);font-size:12px;">';
1469	  html += "现金 ¥" + cash + " · 背包 " + usedSlots + "/" + capacity + "</p>";
1470	  html += '<div style="max-height:420px;overflow-y:auto;">';
1471	
1472	  var ingredientGoods = [];
1473	  if (typeof GOODS !== "undefined") {
1474	    for (var i = 0; i < GOODS.length; i++) {
1475	      if (GOODS[i].isIngredient) ingredientGoods.push(GOODS[i]);
1476	    }
1477	  }
1478	
1479	  // 按类别分组
1480	  var cats = { 主食: [], 蔬菜: [], 肉类: [], 调料: [], 蛋奶: [] };
1481	  var catIcons = { 主食: "🍚", 蔬菜: "🥬", 肉类: "🥩", 调料: "🧂", 蛋奶: "🥛" };
1482	
1483	  // 从 items.js 获取食材类型
1484	  for (var i = 0; i < ingredientGoods.length; i++) {
1485	    var g = ingredientGoods[i];
1486	    var itemDef = typeof getItemById === "function" ? getItemById(g.id) : null;
1487	    var ingType =
1488	      itemDef && itemDef.ingredientType ? itemDef.ingredientType : "其他";
1489	    if (!cats[ingType]) cats[ingType] = [];
1490	    cats[ingType].push({ good: g, itemDef: itemDef });
1491	  }
1492	
1493	  for (var catName in cats) {
1494	    var list = cats[catName];
1495	    if (list.length === 0) continue;
1496	    html +=
1497	      '<h3 style="margin:8px 0 4px;font-size:13px;">' +
1498	      (catIcons[catName] || "📦") +
1499	      " " +
1500	      catName +
1501	      "</h3>";
1502	
1503	    for (var j = 0; j < list.length; j++) {
1504	      var g = list[j].good;
1505	      var itemDef = list[j].itemDef;
1506	      var icon = itemDef ? itemDef.icon : "📦";
1507	      // 本地价格
1508	      var priceMod = 1.0;
1509	      if (typeof LOCATIONS !== "undefined" && LOCATIONS[here]) {
1510	        priceMod =
1511	          (LOCATIONS[here].priceMod && LOCATIONS[here].priceMod[g.id]) || 1.0;
1512	      }
1513	      var price = Math.round(g.basePrice * priceMod * 100) / 100;
1514	
1515	      html +=
1516	        '<div style="display:flex;align-items:center;gap:8px;padding:6px 8px;' +
1517	        'border:1px solid var(--border);border-radius:6px;margin-bottom:4px;">';
1518	      html += '<span style="font-size:18px;">' + icon + "</span>";
1519	      html += '<div style="flex:1;">';
1520	      html +=
1521	        '<div style="font-size:13px;font-weight:500;">' + g.name + "</div>";
1522	      html +=
1523	        '<div style="font-size:10px;color:var(--text-muted);">¥' +
1524	        price +
1525	        "/" +
1526	        g.unit;
1527	      if (itemDef && itemDef.perishDays) {
1528	        html += " · 保鲜" + itemDef.perishDays + "天";
1529	      }
1530	      html += "</div></div>";
1531	      html += '<div style="display:flex;gap:4px;align-items:center;">';
1532	      // 数量选择器
1533	      html +=
1534	        '<button class="btn btn-sm" onclick="ingredientBuyQty(\'' +
1535	        g.id +
1536	        '\', -1)" style="width:24px;height:24px;padding:0;">−</button>';
1537	      html +=
1538	        '<span id="ing_qty_' +
1539	        g.id +
1540	        '" style="min-width:20px;text-align:center;font-size:13px;">0</span>';
1541	      html +=
1542	        '<button class="btn btn-sm" onclick="ingredientBuyQty(\'' +
1543	        g.id +
1544	        '\', 1)" style="width:24px;height:24px;padding:0;">+</button>';
1545	      html +=
1546	        '<button class="btn btn-primary btn-sm" onclick="ingredientBuyConfirm(\'' +
1547	        g.id +
1548	        "'," +
1549	        price +
1550	        ')" style="padding:4px 10px;">买</button>';
1551	      html += "</div></div>";
1552	    }
1553	  }
1554	
1555	  html += "</div>"; // scrollable
1556	  html += '<div style="text-align:center;margin-top:12px;">';
1557	  html +=
1558	    '<button class="btn btn-secondary" onclick="this.closest(\'.modal-overlay\').remove()">关闭</button>';
