1617	      "warning",
1618	    );
1619	    return;
1620	  }
1621	
1622	  // 扣钱
1623	  state.resources.cash -= totalCost;
1624	
1625	  // 加库存（带购买日用于保鲜）
1626	  state.inventory = state.inventory || { items: [], capacity: 20 };
1627	  var existing = null;
1628	  for (var i = 0; i < state.inventory.items.length; i++) {
1629	    if (state.inventory.items[i].id === goodId) {
1630	      existing = state.inventory.items[i];
1631	      break;
1632	    }
1633	  }
1634	  if (existing) {
1635	    existing.qty += qty;
1636	  } else {
1637	    state.inventory.items.push({
1638	      id: goodId,
1639	      qty: qty,
1640	      boughtDay: state.player.day || 0,
1641	      perishDays: (function () {
1642	        var def =
1643	          typeof getItemById === "function" ? getItemById(goodId) : null;
1644	        return def ? def.perishDays : 7;
1645	      })(),
1646	    });
1647	  }
1648	
1649	  // 添加购买记录
1650	  if (typeof addDailyTransaction === "function") {
1651	    addDailyTransaction(state, "expense", "ingredient", totalCost, goodId);
1652	  }
1653	
1654	  StateManager.addMessage(
1655	    "🛒 购买了 " + qty + " 份食材。花费 ¥" + totalCost.toFixed(2),
1656	    "success",
1657	  );
1658	
1659	  // 刷新弹窗
1660	  var overlay = document.querySelector(".modal-overlay");
1661	  if (overlay) overlay.remove();
1662	
1663	  // 重新打开购物窗口
1664	  showIngredientShopModal();
1665	  if (typeof renderAll === "function") renderAll();
1666	}
