1781	
1782	/** 显示家居设施选择弹窗 */
1783	function showHomeActionsModal(state) {
1784	  var homeAmenities =
1785	    typeof getHomeAmenities === "function" ? getHomeAmenities(state) : [];
1786	  if (homeAmenities.length === 0) {
1787	    StateManager.addMessage("🏠 住所没有可用的设施。", "info");
1788	    return;
1789	  }
1790	  var html =
1791	    '<div style="font-size:13px;margin-bottom:10px;color:var(--text-secondary);">选择一项居家活动：</div>';
